    private static void chuckpack$joinMinecraftServer(String addressInput) {
        net.minecraft.client.Minecraft mc = net.minecraft.client.Minecraft.getInstance();

        String host = addressInput;
        int port = 25565;

        int colonIndex = addressInput.lastIndexOf(':');
        if (colonIndex > 0) {
            String portPart = addressInput.substring(colonIndex + 1);
            try {
                port = Integer.parseInt(portPart);
                host = addressInput.substring(0, colonIndex);
            } catch (NumberFormatException ignored) {}
        }

        final String finalHost = host;
        final int finalPort = port;

        mc.execute(() -> {
            try {
                net.minecraft.client.multiplayer.resolver.ServerAddress serverAddress =
                    new net.minecraft.client.multiplayer.resolver.ServerAddress(finalHost, finalPort);
                net.minecraft.client.multiplayer.ServerData serverInfo = new net.minecraft.client.multiplayer.ServerData(
                    finalHost, finalHost + ":" + finalPort,
                    net.minecraft.client.multiplayer.ServerData.Type.OTHER
                );
                net.minecraft.client.gui.screens.Screen returnScreen =
                    mc.gui.screen() != null ? mc.gui.screen() : new net.minecraft.client.gui.screens.TitleScreen();
                net.minecraft.client.gui.screens.ConnectScreen.startConnecting(
                    returnScreen, mc, serverAddress, serverInfo, false,
                    new net.minecraft.client.multiplayer.TransferState(java.util.Map.of(), java.util.Map.of(), false)
                );
                ChatUtils.info("Joining server " + finalHost + ":" + finalPort + "...");
            } catch (Exception e) {
                ChatUtils.error("Failed to join server: " + e.getMessage());
            }
        });
    }

    // .swarm server [address] [random]: as host, broadcast workers to the given IP,
    // or (no address) to whatever server the host is currently on. Random = unique
    // random usernames per worker. Non-host/standalone just joins the given IP directly.
    private static int chuckpack$serverCmd(String address, boolean random) {
        Swarm swarm = Modules.get().get(Swarm.class);
        net.minecraft.client.Minecraft mc = net.minecraft.client.Minecraft.getInstance();

        if (address != null && address.equalsIgnoreCase("random")) {
            address = null;
            random = true;
        }

        if (swarm.isActive() && swarm.isHost()) {
            String target = address;
            if (target == null || target.isEmpty()) {
                try {
                    if (mc != null && mc.getCurrentServer() != null && mc.getCurrentServer().ip != null
                        && !mc.getCurrentServer().ip.trim().isEmpty()) {
                        target = mc.getCurrentServer().ip.trim();
                    }
                } catch (Throwable ignored) {}
                if (target == null || target.isEmpty()) {
                    ChatUtils.error("You must be on a server or provide an IP: .swarm server <ip> [random]");
                    return 0;
                }
            }
            meteordevelopment.meteorclient.systems.modules.misc.swarm.SwarmConnection[] conns = swarm.host.getConnections();
            int nextId = 1;
            for (int i = 0; i < conns.length; i++) {
                if (conns[i] != null) {
                    conns[i].messageToSend = "swarm server " + target + "###ID###" + nextId + (random ? "###RANDOM###" : "");
                    nextId++;
                }
            }
            ChatUtils.info("Telling %d workers to join (highlight)%s%s", nextId - 1, target, random ? " (random names)" : "");
        } else {
            if (address == null || address.isEmpty()) {
                ChatUtils.error("Usage: .swarm server <ip> [random]");
                return 0;
            }
            chuckpack$joinMinecraftServer(address);
        }
        return 1;
    }

