    private static final java.util.Map<String, Integer> chuckpack$workerIds = new java.util.HashMap<>();
    private static final java.util.Set<Integer> chuckpack$usedIds = new java.util.HashSet<>();

    private static void chuckpack$sendNames(Swarm swarm) {
        net.minecraft.client.Minecraft mc = net.minecraft.client.Minecraft.getInstance();
        if (mc.player == null || mc.level == null) return;

        java.util.List<String> currentPlayers = new java.util.ArrayList<>();
        for (net.minecraft.world.entity.player.Player p : mc.level.players()) {
            if (p == mc.player) continue;
            currentPlayers.add(p.getName().getString());
        }

        chuckpack$workerIds.entrySet().removeIf(e -> !currentPlayers.contains(e.getKey()));
        chuckpack$usedIds.retainAll(chuckpack$workerIds.values());

        for (String name : currentPlayers) {
            if (!chuckpack$workerIds.containsKey(name)) {
                int id = 1;
                while (chuckpack$usedIds.contains(id)) id++;
                chuckpack$workerIds.put(name, id);
                chuckpack$usedIds.add(id);
            }
        }

        StringBuilder sb = new StringBuilder("swarm ChuckPack-sync ");
        boolean first = true;
        for (String name : currentPlayers) {
            if (!first) sb.append(",");
            sb.append(name);
            first = false;
        }
        if (!first) {
            net.chuck.chuckpack.modules.combat.SwarmGuard guard = net.chuck.chuckpack.modules.combat.SwarmGuard.get();
            sb.append("###CFG###");
            sb.append(guard.attackMode.get().name()).append(",");
            sb.append(guard.meleeRange.get()).append(",");
            sb.append(guard.meleeVerticalRange.get()).append(",");
            sb.append(guard.rangedRange.get()).append(",");
            sb.append(guard.rangedVerticalRange.get());

            sb.append("###IDS###");
            boolean firstId = true;
            for (java.util.Map.Entry<String, Integer> entry : chuckpack$workerIds.entrySet()) {
                if (!firstId) sb.append(";");
                sb.append(entry.getKey()).append(":").append(entry.getValue());
                firstId = false;
            }

            swarm.host.sendMessage(sb.toString());
        }
    }

    private static void chuckpack$activateGuardOnWorker(String specifiedName) {
        net.minecraft.client.Minecraft.getInstance().execute(() -> {
            String hostName = specifiedName;
            if (hostName == null) {
                net.minecraft.client.Minecraft mc = net.minecraft.client.Minecraft.getInstance();
                if (mc.player != null && mc.level != null) {
                    double closest = Double.MAX_VALUE;
                    for (net.minecraft.world.entity.player.Player p : mc.level.players()) {
                        if (p == mc.player) continue;
                        double dist = mc.player.distanceTo(p);
                        if (dist < closest) {
                            closest = dist;
                            hostName = p.getName().getString();
                        }
                    }
                }
            }
            if (hostName != null) {
                net.chuck.chuckpack.modules.combat.SwarmGuard.get().activate(hostName);
                ChatUtils.info("Swarm Guard activated \u2014 following " + hostName);
            } else {
                ChatUtils.error("Could not find a host player to guard.");
            }
        });
    }
